                        return false;
                    }
                    err.highlighted_help(vec![
                        StringPart::normal(format!("the trait `{}` ", cand.print_trait_sugared())),
                        StringPart::highlighted("is"),
                        StringPart::normal(" implemented for `"),
                        StringPart::highlighted(cand.self_ty().to_string()),
                        StringPart::normal("`"),
                    ]);

